INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Fix and Flip Series : Time Hacks', 'The Bay Area Private Money for Real Estate Investors Meetup', 'Real Estate', 'MONDAY 5 PM PST 7 PM CST 8 PM EST [SIGN UP HERE](https://link.elitereimm.com/widget/form/wSbrsstjtpMx77vSSif7?am_id=debbie5574) Use CRM,', 'MONDAY 5 PM PST 7 PM CST 8 PM EST [SIGN UP HERE](https://link.elitereimm.com/widget/form/wSbrsstjtpMx77vSSif7?am_id=debbie5574) Use CRM, systems, automation, and AI to run flips more efficiently without letting every project take over your life. Fixing and flipping can become a full-time job fast. Contractors need answers. Materials need to be ordered. Draws need to be tracked. Budgets change. Inspections get scheduled. Properties need to be marketed. And somehow you are still supposed to find More info: https://www.meetup.com/bay-area-private-money-for-real-estate-investors-meetup/events/316784938/', '2026-10-12T17:00:00-07:00', 'Online event', 'Online event', 'San Jose', 'CA', '', 37.29, -121.9, 'The Bay Area Private Money for Real Estate Investors Meetup', 2, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/bay-area-private-money-for-real-estate-investors-meetup/events/316784938/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('[Virtual] Simple Real Estate Strategies That Work (Fun, Free, & Gets You Paid!)', 'The Bay Area Private Money for Real Estate Investors Meetup', 'Real Estate', '**Most real estate trainings are like bad lectures:** boring, overloaded with information, and leaving you feeling like you’ll need weeks', '**Most real estate trainings are like bad lectures:** boring, overloaded with information, and leaving you feeling like you’ll need weeks of prep just to get started (or worst of all, they just want to sell you their expensive course or coaching). **We decided to do the exact opposite**—and hundreds of agents now agree. Join us **LIVE (virtual) every Wednesday at 9:00 AM CST** for a zero-fluff, action-packed call where active, top-producing agents openly share exactly what’s working right More info: https://www.meetup.com/bay-area-private-money-for-real-estate-investors-meetup/events/316694213/', '2026-10-14T07:00:00-07:00', 'Online event', 'Online event', 'San Jose', 'CA', '', 37.29, -121.9, 'The Bay Area Private Money for Real Estate Investors Meetup', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/bay-area-private-money-for-real-estate-investors-meetup/events/316694213/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('RE-AI Advantage Lab: Turn AI Into Your Real Estate Advantage', 'The Bay Area Private Money for Real Estate Investors Meetup', 'Real Estate', 'AI is changing what “work” looks like for real estate agents. Tasks that used to take hours can now take minutes. Marketing can be created', 'AI is changing what “work” looks like for real estate agents. Tasks that used to take hours can now take minutes. Marketing can be created faster. Follow up can be smarter. Content can be generated almost instantly. But most agents are still trying to figure out **how to actually use AI in their day-to-day business.** That is exactly what we will be exploring inside the **RE-AI Advantage Lab.** This weekly training is designed specifically for real estate agents who want to learn how to use AI More info: https://www.meetup.com/bay-area-private-money-for-real-estate-investors-meetup/events/316695029/', '2026-10-14T08:00:00-07:00', 'Online event', 'Online event', 'San Jose', 'CA', '', 37.29, -121.9, 'The Bay Area Private Money for Real Estate Investors Meetup', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/bay-area-private-money-for-real-estate-investors-meetup/events/316695029/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Real Estate Agent Virtual Coffee Mastermind', 'The Bay Area Private Money for Real Estate Investors Meetup', 'Real Estate', 'Start your morning... with a coffee & friends from all over the country. Don''t miss out on our live (virtual) networking event every', 'Start your morning... with a coffee & friends from all over the country. Don''t miss out on our live (virtual) networking event every Thursday morning. It''s the perfect opportunity to build relationships with Realtors across the state and across the country (sometimes even on the other side of the world) that will serve your clients well when they need a referral. We have a short educational/informative presentation at the beginning of the meeting and then go into 3 or 4 person breakout rooms More info: https://www.meetup.com/bay-area-private-money-for-real-estate-investors-meetup/events/316709338/', '2026-10-15T07:00:00-07:00', 'Online event', 'Online event', 'San Jose', 'CA', '', 37.29, -121.9, 'The Bay Area Private Money for Real Estate Investors Meetup', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/bay-area-private-money-for-real-estate-investors-meetup/events/316709338/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('IN-PERSON EVENT: How to Buy Investment Property with Rates as Low as 3.75%*', 'Real Estate Investing-Free Education & Mentoring (South Bay)', 'Real Estate', 'Real estate investing in 2026 looks very different than it did just a few years ago. In many markets, interest rates remain elevated,', 'Real estate investing in 2026 looks very different than it did just a few years ago. In many markets, interest rates remain elevated, inventory dynamics are shifting, and insurance costs are rising in certain areas. As a result, many investors are asking: **Is it still possible to achieve strong returns in today’s market? The answer is YES**—but only if you understand where the opportunities have moved and how to structure deals correctly. You’ll hear directly from Scott Pastel, Vice President More info: https://www.meetup.com/bay-area-real-estate-investing-free-education-mentoring/events/316489239/', '2026-10-13T18:00:00-07:00', 'Sonesta Select San Jose Airport', '1727 Technology Drive', 'San Jose', 'CA', '', 37.35, -121.88, 'Real Estate Investing-Free Education & Mentoring (South Bay)', 1, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/bay-area-real-estate-investing-free-education-mentoring/events/316489239/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('ONLINE: INSIDE A $100M MORTGAGE FUND: Q3 EARNINGS & WHY INVEST WITH US', 'Real Estate Investing-Free Education & Mentoring (South Bay)', 'Real Estate', 'Utilize our *Audited* Mortgage Fund and earn safe and consistent returns—without compromising liquidity—8.45% per year! Structured with a', 'Utilize our *Audited* Mortgage Fund and earn safe and consistent returns—without compromising liquidity—8.45% per year! Structured with a low $25,000 minimum and a mere 12 month commitment, our Fund is the perfect opportunity Marshall Reddick clients—including those leveraging a self-directed retirement account—to tap into the Residential Real Estate Private Credit Market. Since inception, over the past 6.5 years, we’ve slowly, strategically and organically grown on our march to $100M. The More info: https://www.meetup.com/bay-area-real-estate-investing-free-education-mentoring/events/316356509/', '2026-10-28T18:00:00-07:00', 'Online event', 'Online event', 'San Jose', 'CA', '', 37.35, -121.88, 'Real Estate Investing-Free Education & Mentoring (South Bay)', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/bay-area-real-estate-investing-free-education-mentoring/events/316356509/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('ONLINE EVENT: Year-End Investment Deals Close-Out', 'Real Estate Investing-Free Education & Mentoring (South Bay)', 'Real Estate', 'Mortgage rates just climbed back above 7%, and sellers are feeling the pressure. With year-end sales goals to hit and finished homes to', 'Mortgage rates just climbed back above 7%, and sellers are feeling the pressure. With year-end sales goals to hit and finished homes to move, sellers, developers and builders are offering **amazing pricing and incentives including rate buydowns, free property management, closing cost credits and more.** For investors, this is typically the best buying window of the year! Join us for this complimentary webinar to learn how to turn seller motivation into your advantage. We''ll show you how to lock More info: https://www.meetup.com/bay-area-real-estate-investing-free-education-mentoring/events/316900064/', '2026-11-17T17:00:00-08:00', 'Online event', 'Online event', 'San Jose', 'CA', '', 37.35, -121.88, 'Real Estate Investing-Free Education & Mentoring (South Bay)', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/bay-area-real-estate-investing-free-education-mentoring/events/316900064/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('ONLINE EVENT: Sell Smart, Defer the Tax: A Practical Guide to 1031 Exchanges', 'Real Estate Investing-Free Education & Mentoring (South Bay)', 'Real Estate', 'Real estate investors are looking beyond their local markets for stronger cash flow, greater affordability, and long-term growth, and many', 'Real estate investors are looking beyond their local markets for stronger cash flow, greater affordability, and long-term growth, and many are using 1031 Exchanges to strategically reposition their portfolios. Join us for an educational session designed for investors who want to better understand how a 1031 Exchange may help them **sell qualifying investment property, potentially defer capital gains taxes, and reinvest in new opportunities** across the country. Featured speaker Aristotle More info: https://www.meetup.com/bay-area-real-estate-investing-free-education-mentoring/events/316913799/', '2026-12-01T17:00:00-08:00', 'Online event', 'Online event', 'San Jose', 'CA', '', 37.35, -121.88, 'Real Estate Investing-Free Education & Mentoring (South Bay)', 2, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/bay-area-real-estate-investing-free-education-mentoring/events/316913799/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
