INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Self Love Workshop', 'Body Language Training | Los Angeles', 'General Networking', '**The way you treat yourself is running your whole life, and most of us treat ourselves worse than we''d ever treat someone we love.** You''d', '**The way you treat yourself is running your whole life, and most of us treat ourselves worse than we''d ever treat someone we love.** You''d never speak to a friend the way you speak to yourself. You''d never hold them to the standard you hold yourself to, or withhold your kindness the way you withhold it from you. So why is it so hard to turn that warmth inward? Because somewhere, you learned your worth was conditional. That you had to earn it, perform for it, get it right first. And underneath More info: https://www.meetup.com/body-language-training-los-angeles/events/316800506/', '2026-10-27T16:30:00-07:00', 'Online event', 'Online event', 'Los Angeles', 'CA', '', 33.97, -118.24, 'Body Language Training | Los Angeles', 2, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/body-language-training-los-angeles/events/316800506/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Authenticity in Action', 'Body Language Training | Los Angeles', 'General Networking', '**Do you ever feel like you''re performing instead of showing up as your real self? You''re not alone — and it was never your fault.**', '**Do you ever feel like you''re performing instead of showing up as your real self? You''re not alone — and it was never your fault.** Somewhere, you learned that being fully yourself wasn''t safe. So you started performing. You got good at it, agreeable, easy, "it''s fine." And underneath the performance has been a quiet weight you''ve carried for years: the fear of being too much, the guilt of taking up space, the shame of needing anything at all. I built this work to free people from exactly More info: https://www.meetup.com/body-language-training-los-angeles/events/316843408/', '2026-12-01T16:30:00-08:00', 'Online event', 'Online event', 'Los Angeles', 'CA', '', 33.97, -118.24, 'Body Language Training | Los Angeles', 2, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/body-language-training-los-angeles/events/316843408/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
