INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Monday Multipliers', 'Bold, Beautiful & In Business - Atlanta Women''s Networking', 'Women in Business', '**Maximize Monday** is an early-morning networking and strategy gathering designed for driven entrepreneurs who refuse to drift into their', '**Maximize Monday** is an early-morning networking and strategy gathering designed for driven entrepreneurs who refuse to drift into their week unprepared. This is not just another networking meeting. It’s a focused, high-energy environment where business owners come together before the week begins to: * Clarify top priorities * Strengthen strategic connections * Share opportunities and insights * Increase accountability * Build real momentum We believe how you start your week determines how More info: https://www.meetup.com/bold-women-entrepreneurs-networking-atlanta/events/316663641/', '2026-10-12T09:30:00-04:00', 'Online event', 'Online event', 'Atlanta', 'GA', '', 33.88, -84.37, 'Bold, Beautiful & In Business - Atlanta Women''s Networking', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/bold-women-entrepreneurs-networking-atlanta/events/316663641/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('LinkedIn Authority Builders', 'Bold, Beautiful & In Business - Atlanta Women''s Networking', 'Women in Business', 'Want to become the go-to expert in your industry? Join us each week for LinkedIn Authority Builders, a collaborative community designed for', 'Want to become the go-to expert in your industry? Join us each week for LinkedIn Authority Builders, a collaborative community designed for professionals, entrepreneurs, and business leaders who want to leverage the power of LinkedIn and AI to build influence, strengthen relationships, and generate new opportunities. Hosted by Eileen Snover, this interactive weekly gathering will help you turn your expertise into visibility and visibility into business growth. You''ll Discover How To: ✅ Optimize More info: https://www.meetup.com/bold-women-entrepreneurs-networking-atlanta/events/316681510/', '2026-10-13T13:00:00-04:00', 'Online event', 'Online event', 'Atlanta', 'GA', '', 33.88, -84.37, 'Bold, Beautiful & In Business - Atlanta Women''s Networking', 2, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/bold-women-entrepreneurs-networking-atlanta/events/316681510/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Positively Women''s Networking', 'Bold, Beautiful & In Business - Atlanta Women''s Networking', 'Women in Business', 'This club is a professional safe haven for women in business, led by women in business. It’s where you’ll find a supportive, uplifting', 'This club is a professional safe haven for women in business, led by women in business. It’s where you’ll find a supportive, uplifting community dedicated to helping you thrive, not just survive. We believe in lifting each other up, sharing real-world advice, and building a powerful network rooted in trust and genuine support. Come find your village and gain the encouragement you need to reach your highest goals. **From Confident to Unstoppable:** Learn the keys to owning your voice, mastering More info: https://www.meetup.com/bold-women-entrepreneurs-networking-atlanta/events/315752179/', '2026-10-13T15:00:00-04:00', 'Online event', 'Online event', 'Atlanta', 'GA', '', 33.88, -84.37, 'Bold, Beautiful & In Business - Atlanta Women''s Networking', 2, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/bold-women-entrepreneurs-networking-atlanta/events/315752179/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Online Business Networking', 'Bold, Beautiful & In Business - Atlanta Women''s Networking', 'Women in Business', 'You''ve probably asked the same questions we hear all the time: Why is good networking so hard to find? Why does it feel so transactional?', 'You''ve probably asked the same questions we hear all the time: Why is good networking so hard to find? Why does it feel so transactional? The truth is, most networking isn''t designed for you. Join this call to learn how CIBN is built from tip to toe to be member-serving. We believe that our success lives and dies in the success of our members—and we''ve designed everything around that philosophy. [Checkout our website for more high quality networking events](https://cibnconnect.com/) More info: https://www.meetup.com/bold-women-entrepreneurs-networking-atlanta/events/316710738/', '2026-10-15T12:00:00-04:00', 'Online event', 'Online event', 'Atlanta', 'GA', '', 33.88, -84.37, 'Bold, Beautiful & In Business - Atlanta Women''s Networking', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/bold-women-entrepreneurs-networking-atlanta/events/316710738/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Vegas Bootstrappers Breakfast Roundtable', 'Bootstrappers Breakfast - Las Vegas Startups', 'Founders & Startups', '**New location: The Coffee Press (at Paseo Verde Library)** 280 S. Green Valley Parkway Henderson, Nevada Come join entrepreneurs who eat', '**New location: The Coffee Press (at Paseo Verde Library)** 280 S. Green Valley Parkway Henderson, Nevada Come join entrepreneurs who eat problems for breakfast®. At a Bootstrappers Breakfast® we have serious conversations about growing a business based on internal cashflow and organic profit. This group offers a combination of brainstorming, education, peer accountability and support in a group setting to sharpen your business and personal skills. The other attendees will all be in startups. More info: https://www.meetup.com/bootstrappers-breakfast-las-vegas-startups/events/316696652/', '2026-11-10T09:00:00-08:00', 'Paseo Verde Library', '280 South Green Valley Parkway', 'Henderson', 'NV', '', 36.17, -115.12, 'Bootstrappers Breakfast - Las Vegas Startups', 7, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/bootstrappers-breakfast-las-vegas-startups/events/316696652/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
